<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{IkontrolInstance,IkontrolUpgradeAudit}; use App\Services\AuditService; use App\Services\Upgrade\InstanceUpgradeAuditService; use Illuminate\Http\Request; use Throwable;
class InstanceUpgradeController extends Controller {
 public function analyze(IkontrolInstance$instance,Request$request,InstanceUpgradeAuditService$service,AuditService$audit){$data=$request->validate(['target_version'=>['required','string','max:50','regex:/\A[0-9A-Za-z._-]+\z/']]);$audit->record('INSTANCE_UPGRADE_AUDIT_STARTED','Auditoría de upgrade iniciada.',$instance,['target_version'=>$data['target_version']]);try{$result=$service->audit($instance,$data['target_version']);$audit->record('INSTANCE_UPGRADE_AUDIT_COMPLETED','Auditoría de upgrade completada.',$instance,['upgrade_audit_id'=>$result->id,'compatibility'=>$result->compatibility]);return redirect()->route('instances.upgrade-audits.show',[$instance,$result])->with('success','Análisis de versión completado sin modificar la instancia.');}catch(Throwable$e){report($e);return back()->with('error','No fue posible completar la auditoría: '.$e->getMessage());}}
 public function show(IkontrolInstance$instance,IkontrolUpgradeAudit$upgradeAudit){abort_unless($upgradeAudit->ikontrol_instance_id===$instance->id,404);$upgradeAudit->load('items');return view('admin.instances.upgrade-audit',compact('instance','upgradeAudit'));}
 public function dryRun(IkontrolInstance$instance,IkontrolUpgradeAudit$upgradeAudit,InstanceUpgradeAuditService$service,AuditService$audit){abort_unless($upgradeAudit->ikontrol_instance_id===$instance->id,404);$plan=$service->regeneratePlan($upgradeAudit->load('items'));$audit->record('INSTANCE_UPGRADE_DRY_RUN_GENERATED','Dry-run de upgrade generado.',$instance,['upgrade_audit_id'=>$upgradeAudit->id,'compatibility'=>$plan['compatibility']]);return back()->with('success','Dry-run regenerado. No se ejecutó ningún cambio.');}
}
